#define OUI_MAM_COUNT (sizeof(ouiMamKeys) / sizeof(ouiMamKeys[0]))

template <typename K>
inline const char *ouiBlockFind(const K *keys,
                                const char *const *names,
                                int count, K key)
{
    int lo = 0;
    int hi = count - 1;

    while (lo <= hi)
    {
        int mid = (lo + hi) / 2;

        if (keys[mid] == key)
            return names[mid];

        if (keys[mid] < key)
            lo = mid + 1;
        else
            hi = mid - 1;
    }

    return nullptr;
}

