#define OUI_MAS_COUNT (sizeof(ouiMasKeys) / sizeof(ouiMasKeys[0]))

/*
 * Vendor of an address: its 36-bit block (MA-S, IAB), its
 * 28-bit block (MA-M), else its 24-bit OUI (MA-L). bits,
 * if given, gets the size of the prefix that matched.
 */
inline const char *ouiLookupMac(const uint8_t *mac,
                                uint8_t *bits = nullptr)
{
    uint64_t k36 = ((uint64_t)mac[0] << 28) |
                   ((uint64_t)mac[1] << 20) |
                   ((uint64_t)mac[2] << 12) |
                   ((uint64_t)mac[3] << 4) | (mac[4] >> 4);
    uint32_t k28 = (uint32_t)(k36 >> 8);

    uint8_t size = 36;
    const char *name = ouiBlockFind(ouiMasKeys, ouiMasNames,
                                    OUI_MAS_COUNT, k36);

    if (name == nullptr)
    {
        size = 28;
        name = ouiBlockFind(ouiMamKeys, ouiMamNames,
                            OUI_MAM_COUNT, k28);
    }

    if (name == nullptr)
    {
        size = 24;
        name = ouiLookupFull((uint32_t)(k36 >> 12));
    }

    if (bits != nullptr)
        *bits = name != nullptr ? size : 0;

    return name;
}
